import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    term1 = x1**2 + x2**2
    skew_term = (x1 + x2)**3 * 0.001
    return 0.01 * (term1 + skew_term)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return (x1**2) + (0.5 * x2**2) + (x1 * x2) + (0.1 * np.exp(x1))

import numpy as np

